CREATE TABLE `background_jobs` (
	`id` bigint unsigned AUTO_INCREMENT NOT NULL,
	`family_id` bigint unsigned NOT NULL,
	`media_id` bigint unsigned NOT NULL,
	`generation` bigint unsigned NOT NULL,
	`recipe_id` smallint unsigned NOT NULL,
	`job_type` enum('MEDIA_PROBE','IMAGE_DERIVATIVES','VIDEO_POSTER') NOT NULL,
	`state` enum('QUEUED','RUNNING','RETRY_WAIT','SUCCEEDED','FAILED','CANCELLED') NOT NULL DEFAULT 'QUEUED',
	`attempts` tinyint unsigned NOT NULL DEFAULT 0,
	`max_attempts` tinyint unsigned NOT NULL DEFAULT 3,
	`available_at` datetime(3) NOT NULL,
	`locked_at` datetime(3),
	`heartbeat_at` datetime(3),
	`locked_until` datetime(3),
	`worker_id` binary(16),
	`lease_epoch` bigint unsigned NOT NULL DEFAULT 0,
	`last_failure_code` enum('UNSUPPORTED_FORMAT','CAPABILITY_UNAVAILABLE','MALFORMED_MEDIA','INPUT_LIMIT','OUTPUT_LIMIT','PROCESS_TIMEOUT','RESOURCE_LIMIT','TEMPORARY_IO','STORAGE_UNAVAILABLE','ORIGINAL_MISSING','ORIGINAL_CORRUPT','DERIVED_INTEGRITY','WORKER_LOST','DB_UNAVAILABLE','COMMIT_OUTCOME_UNKNOWN'),
	`created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
	`updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
	`finished_at` datetime(3),
	CONSTRAINT `background_jobs_id` PRIMARY KEY(`id`),
	CONSTRAINT `uq_background_jobs_identity` UNIQUE(`family_id`,`media_id`,`generation`,`recipe_id`,`job_type`),
	CONSTRAINT `uq_background_jobs_family_media_id` UNIQUE(`family_id`,`media_id`,`id`),
	CONSTRAINT `chk_background_jobs_generation` CHECK(`background_jobs`.`generation` >= 1),
	CONSTRAINT `chk_background_jobs_recipe` CHECK(`background_jobs`.`recipe_id` >= 1),
	CONSTRAINT `chk_background_jobs_attempts` CHECK(`background_jobs`.`attempts` <= `background_jobs`.`max_attempts` AND `background_jobs`.`max_attempts` BETWEEN 1 AND 3),
	CONSTRAINT `chk_background_jobs_lease` CHECK((`background_jobs`.`state` = 'RUNNING' AND `background_jobs`.`locked_at` IS NOT NULL AND `background_jobs`.`heartbeat_at` IS NOT NULL AND `background_jobs`.`locked_until` IS NOT NULL AND `background_jobs`.`worker_id` IS NOT NULL AND `background_jobs`.`lease_epoch` > 0 AND `background_jobs`.`locked_at` <= `background_jobs`.`heartbeat_at` AND `background_jobs`.`heartbeat_at` < `background_jobs`.`locked_until`) OR (`background_jobs`.`state` <> 'RUNNING' AND `background_jobs`.`locked_at` IS NULL AND `background_jobs`.`heartbeat_at` IS NULL AND `background_jobs`.`locked_until` IS NULL AND `background_jobs`.`worker_id` IS NULL)),
	CONSTRAINT `chk_background_jobs_terminal` CHECK((`background_jobs`.`state` IN ('SUCCEEDED','FAILED','CANCELLED') AND `background_jobs`.`finished_at` IS NOT NULL AND `background_jobs`.`finished_at` >= `background_jobs`.`created_at`) OR (`background_jobs`.`state` NOT IN ('SUCCEEDED','FAILED','CANCELLED') AND `background_jobs`.`finished_at` IS NULL)),
	CONSTRAINT `chk_background_jobs_failure` CHECK((`background_jobs`.`state` IN ('FAILED','RETRY_WAIT') AND `background_jobs`.`last_failure_code` IS NOT NULL) OR (`background_jobs`.`state` IN ('QUEUED','SUCCEEDED','CANCELLED') AND `background_jobs`.`last_failure_code` IS NULL) OR `background_jobs`.`state` = 'RUNNING')
) ENGINE=InnoDB DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
