CREATE TABLE `derived_assets` (
	`id` bigint unsigned AUTO_INCREMENT NOT NULL,
	`family_id` bigint unsigned NOT NULL,
	`media_id` bigint unsigned NOT NULL,
	`generation` bigint unsigned NOT NULL,
	`recipe_id` smallint unsigned NOT NULL,
	`kind` enum('THUMBNAIL','PREVIEW','VIDEO_POSTER') NOT NULL,
	`state` enum('RESERVED','PUBLISHING','READY','MISSING','FAILED') NOT NULL DEFAULT 'RESERVED',
	`reserved_bytes` bigint unsigned NOT NULL,
	`byte_size` bigint unsigned,
	`sha256` binary(32),
	`width` int unsigned,
	`height` int unsigned,
	`output_mime` varchar(127),
	`producer_job_id` bigint unsigned NOT NULL,
	`producer_lease_epoch` bigint unsigned,
	`failure_code` enum('UNSUPPORTED_FORMAT','CAPABILITY_UNAVAILABLE','MALFORMED_MEDIA','INPUT_LIMIT','OUTPUT_LIMIT','PROCESS_TIMEOUT','RESOURCE_LIMIT','TEMPORARY_IO','STORAGE_UNAVAILABLE','ORIGINAL_MISSING','ORIGINAL_CORRUPT','DERIVED_INTEGRITY','WORKER_LOST','DB_UNAVAILABLE','COMMIT_OUTCOME_UNKNOWN'),
	`published_at` datetime(3),
	`cleaned_at` datetime(3),
	`created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
	`updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
	CONSTRAINT `derived_assets_id` PRIMARY KEY(`id`),
	CONSTRAINT `uq_derived_assets_identity` UNIQUE(`family_id`,`media_id`,`generation`,`recipe_id`,`kind`),
	CONSTRAINT `chk_derived_assets_generation` CHECK(`derived_assets`.`generation` >= 1),
	CONSTRAINT `chk_derived_assets_recipe` CHECK(`derived_assets`.`recipe_id` >= 1),
	CONSTRAINT `chk_derived_assets_reservation` CHECK((`derived_assets`.`kind` = 'THUMBNAIL' AND `derived_assets`.`reserved_bytes` BETWEEN 1 AND 524288) OR (`derived_assets`.`kind` = 'PREVIEW' AND `derived_assets`.`reserved_bytes` BETWEEN 1 AND 4194304) OR (`derived_assets`.`kind` = 'VIDEO_POSTER' AND `derived_assets`.`reserved_bytes` BETWEEN 1 AND 1048576)),
	CONSTRAINT `chk_derived_assets_bytes_digest` CHECK((`derived_assets`.`byte_size` IS NULL AND `derived_assets`.`sha256` IS NULL) OR (`derived_assets`.`byte_size` IS NOT NULL AND `derived_assets`.`sha256` IS NOT NULL AND `derived_assets`.`byte_size` > 0 AND `derived_assets`.`byte_size` <= `derived_assets`.`reserved_bytes`)),
	CONSTRAINT `chk_derived_assets_dimensions` CHECK((`derived_assets`.`width` IS NULL AND `derived_assets`.`height` IS NULL) OR (`derived_assets`.`width` IS NOT NULL AND `derived_assets`.`height` IS NOT NULL AND `derived_assets`.`width` > 0 AND `derived_assets`.`height` > 0)),
	CONSTRAINT `chk_derived_assets_published_payload` CHECK(`derived_assets`.`state` NOT IN ('PUBLISHING','READY') OR (`derived_assets`.`byte_size` IS NOT NULL AND `derived_assets`.`sha256` IS NOT NULL AND `derived_assets`.`width` IS NOT NULL AND `derived_assets`.`height` IS NOT NULL AND `derived_assets`.`output_mime` = 'image/webp' AND `derived_assets`.`producer_lease_epoch` IS NOT NULL AND `derived_assets`.`producer_lease_epoch` > 0)),
	CONSTRAINT `chk_derived_assets_ready` CHECK(`derived_assets`.`state` <> 'READY' OR (`derived_assets`.`published_at` IS NOT NULL AND `derived_assets`.`cleaned_at` IS NULL AND `derived_assets`.`published_at` >= `derived_assets`.`created_at`)),
	CONSTRAINT `chk_derived_assets_failure` CHECK((`derived_assets`.`state` IN ('MISSING','FAILED') AND `derived_assets`.`failure_code` IS NOT NULL) OR (`derived_assets`.`state` NOT IN ('MISSING','FAILED') AND `derived_assets`.`failure_code` IS NULL)),
	CONSTRAINT `chk_derived_assets_times` CHECK((`derived_assets`.`published_at` IS NULL OR `derived_assets`.`published_at` >= `derived_assets`.`created_at`) AND (`derived_assets`.`cleaned_at` IS NULL OR `derived_assets`.`cleaned_at` >= `derived_assets`.`created_at`))
) ENGINE=InnoDB DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
