	CONSTRAINT `chk_media_items_raw_dimensions` CHECK((`media_items`.`raw_width` IS NULL AND `media_items`.`raw_height` IS NULL) OR (`media_items`.`raw_width` IS NOT NULL AND `media_items`.`raw_height` IS NOT NULL AND `media_items`.`raw_width` > 0 AND `media_items`.`raw_height` > 0)),
	CONSTRAINT `chk_media_items_display_dimensions` CHECK((`media_items`.`display_width` IS NULL AND `media_items`.`display_height` IS NULL) OR (`media_items`.`display_width` IS NOT NULL AND `media_items`.`display_height` IS NOT NULL AND `media_items`.`display_width` > 0 AND `media_items`.`display_height` > 0)),
	CONSTRAINT `chk_media_items_duration` CHECK(`media_items`.`duration_ms` IS NULL OR `media_items`.`duration_ms` <= 86400000),
	CONSTRAINT `chk_media_items_orientation` CHECK(`media_items`.`orientation` IS NULL OR `media_items`.`orientation` BETWEEN 1 AND 8),
	CONSTRAINT `chk_media_items_video_rotation` CHECK(`media_items`.`video_rotation_degrees` IS NULL OR `media_items`.`video_rotation_degrees` IN (0,90,180,270)),
	CONSTRAINT `chk_media_items_animated_boolean` CHECK(`media_items`.`is_animated` IN (0,1)),
	CONSTRAINT `chk_media_items_motion_boolean` CHECK(`media_items`.`motion_hint` IN (0,1)),
	CONSTRAINT `chk_media_items_gps` CHECK((`media_items`.`gps_latitude` IS NULL AND `media_items`.`gps_longitude` IS NULL) OR (`media_items`.`gps_latitude` IS NOT NULL AND `media_items`.`gps_longitude` IS NOT NULL AND `media_items`.`gps_latitude` BETWEEN -90 AND 90 AND `media_items`.`gps_longitude` BETWEEN -180 AND 180)),
	CONSTRAINT `chk_media_items_capture` CHECK((`media_items`.`captured_time_status` = 'ABSENT' AND `media_items`.`captured_source` = 'NONE' AND `media_items`.`captured_local_at` IS NULL AND `media_items`.`captured_at_utc` IS NULL AND `media_items`.`captured_offset_minutes` IS NULL) OR (`media_items`.`captured_time_status` = 'OFFSET_UNKNOWN' AND `media_items`.`captured_source` <> 'NONE' AND `media_items`.`captured_local_at` IS NOT NULL AND `media_items`.`captured_at_utc` IS NULL AND `media_items`.`captured_offset_minutes` IS NULL) OR (`media_items`.`captured_time_status` = 'OFFSET_KNOWN' AND `media_items`.`captured_source` <> 'NONE' AND `media_items`.`captured_local_at` IS NOT NULL AND `media_items`.`captured_at_utc` IS NOT NULL AND `media_items`.`captured_offset_minutes` IS NOT NULL AND `media_items`.`captured_offset_minutes` BETWEEN -840 AND 840 AND (ABS(`media_items`.`captured_offset_minutes`) < 840 OR MOD(`media_items`.`captured_offset_minutes`,60) = 0))),
